module.exports = async function(context, event) {
  const body = event.body || '';
  const redacted = body.replace(/\b\d{3}-\d{2}-\d{4}\b/g, '[REDACTED_SSN]');
  // forward to moderation and persistence steps (pseudo)
  context.log('redacted', redacted);
